ALTER TABLE contacts ADD COLUMN vk_user_id INTEGER UNIQUE; ALTER TABLE tasks ADD COLUMN vk_peer_id INTEGER, ADD COLUMN vk_group_id INTEGER, ADD COLUMN vk_message_id INTEGER UNIQUE; CREATE INDEX idx_tasks_vk_peer ON tasks(vk_peer_id, vk_group_id); CREATE TABLE vk_group_settings (id TEXT PRIMARY KEY DEFAULT gen_random_uuid(), group_id INTEGER NOT NULL, access_token TEXT NOT NULL, default_creator_id TEXT REFERENCES users(id) ON DELETE SET NULL, assignee_ids TEXT[] DEFAULT ARRAY[]::TEXT[], auto_create_contact BOOLEAN NOT NULL DEFAULT true, is_active BOOLEAN NOT NULL DEFAULT true, last_ts INTEGER, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);